-- Run inside a transaction and roll back: no customer, notification or real-money side effects.
BEGIN;
DO $$
DECLARE c uuid:=gen_random_uuid(); p uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); p2 uuid:=gen_random_uuid(); admin_uid uuid:=gen_random_uuid(); ap2 uuid; ap uuid; own_ap uuid;
 m uuid; m2 uuid; m3 uuid; a jsonb; q jsonb; r jsonb; v int; checks int:=0;
BEGIN
 INSERT INTO auth.users(id,email,raw_user_meta_data) VALUES(c,c::text||'@afrione.test','{"name":"[TEST] Client"}'),(p,p::text||'@afrione.test','{"name":"[TEST] Prestataire"}'),(outsider,outsider::text||'@afrione.test','{"name":"[TEST] Tiers"}'),(p2,p2::text||'@afrione.test','{"name":"[TEST] Electricien"}'),(admin_uid,admin_uid::text||'@afrione.test','{"name":"[TEST] Administrateur"}');
 INSERT INTO users(id,name,role) VALUES(c,'[TEST] Client','client'),(p,'[TEST] Prestataire','artisan'),(outsider,'[TEST] Tiers','client'),(p2,'[TEST] Electricien','artisan'),(admin_uid,'[TEST] Admin','admin') ON CONFLICT(id) DO UPDATE SET name=excluded.name,role=excluded.role;
 INSERT INTO artisan_pros(user_id,metier,kyc_status,is_available,is_test) VALUES(p,'Plomberie','approved',true,true) RETURNING id INTO ap;
 INSERT INTO artisan_pros(user_id,metier,kyc_status,is_available,is_test) VALUES(c,'Plomberie','approved',true,true) RETURNING id INTO own_ap;
 INSERT INTO artisan_pros(user_id,metier,kyc_status,is_available,is_test) VALUES(p2,'Électricité','approved',true,true) RETURNING id INTO ap2;
 BEGIN INSERT INTO missions(client_id,artisan_id,category,is_test) VALUES(c,own_ap,'Plomberie',true); RAISE EXCEPTION 'ASSERT self assignment allowed'; EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE; END IF; END; checks:=checks+1;
 INSERT INTO missions(client_id,category,is_test) VALUES(c,'Plomberie',true) RETURNING id INTO m;
 BEGIN PERFORM mission_workflow_action(m,c,'request_provider',jsonb_build_object('artisan_id',own_ap));RAISE EXCEPTION 'ASSERT self booking allowed';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE; END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,c,'request_provider',jsonb_build_object('artisan_id',ap));
 BEGIN PERFORM mission_workflow_action(m,outsider,'accept_assignment','{}');RAISE EXCEPTION 'ASSERT outsider accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE; END IF;END;checks:=checks+1;
 a:=update_discussion_agreement(m,c,'confirm',0,'{"scope":"Changer le mitigeur de cuisine, hors achat du matériel","discussion":true}');
 BEGIN PERFORM update_discussion_agreement(m,p,'propose',1,'{"scope":"Remplacer le mitigeur de cuisine","reason":"Dépose et pose avec contrôle de l’étanchéité","amount":45000,"supplies":"excluded"}');RAISE EXCEPTION 'ASSERT quote before assignment acceptance';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE; END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,p,'accept_assignment','{}');
 a:=update_discussion_agreement(m,p,'propose',1,'{"scope":"Remplacer le mitigeur de cuisine","reason":"Dépose et pose avec contrôle de l’étanchéité","amount":45000,"supplies":"excluded"}');
 IF (SELECT total_price FROM missions WHERE id=m) IS NOT NULL THEN RAISE EXCEPTION 'ASSERT unaccepted price applied'; END IF;checks:=checks+1;
 a:=update_discussion_agreement(m,c,'counter',2,'{"scope":"Remplacer le mitigeur de cuisine","reason":"Matériel déjà disponible : proposition de budget négociée","amount":38000,"supplies":"excluded"}');
 BEGIN PERFORM update_discussion_agreement(m,c,'accept',3,'{}');RAISE EXCEPTION 'ASSERT client accepted own counter';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 a:=update_discussion_agreement(m,p,'accept_counter',3,'{}');
 BEGIN PERFORM update_discussion_agreement(m,c,'accept',2,'{}');RAISE EXCEPTION 'ASSERT stale quote accepted';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 a:=update_discussion_agreement(m,c,'accept',4,'{}');
 a:=update_discussion_agreement(m,p,'propose',5,'{"scope":"Remplacer le mitigeur de cuisine","reason":"Supplément proposé après nouvel échange avec le client","amount":42000,"supplies":"excluded"}');
 a:=update_discussion_agreement(m,c,'reject',6,'{}');q:=get_client_quote(m,c);
 IF (q->>'total')::int<>38000 THEN RAISE EXCEPTION 'ASSERT rejected increase changed price';END IF;checks:=checks+1;
 IF (q->>'total')::int<>38000 OR (q->>'agreement_version')::int<>5 THEN RAISE EXCEPTION 'ASSERT final price wrong';END IF;checks:=checks+1;
 -- Role and row-level guards, not just a hidden button.
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 BEGIN UPDATE missions SET status='en_route' WHERE id=m;RAISE EXCEPTION 'ASSERT client changed status directly';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;
 BEGIN UPDATE missions SET total_price=1 WHERE id=m;RAISE EXCEPTION 'ASSERT client changed price directly';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','',true);checks:=checks+2;
 BEGIN PERFORM mission_workflow_action(m,c,'start_now','{}');RAISE EXCEPTION 'ASSERT unpaid mission scheduled';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,c,'pay_test',jsonb_build_object('quote_revision',q->>'quote_revision'));
 BEGIN PERFORM update_discussion_agreement(m,p,'propose',5,'{"scope":"Un supplément après paiement du devis","reason":"Tentative de supplément après confirmation et paiement","amount":50000,"supplies":"excluded"}');RAISE EXCEPTION 'ASSERT paid quote changed';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,c,'start_now','{}');IF r->>'status'<>'scheduled' THEN RAISE EXCEPTION 'ASSERT client departed for provider';END IF;checks:=checks+1;
 BEGIN PERFORM mission_workflow_action(m,c,'start_tracking','{}');RAISE EXCEPTION 'ASSERT client declared provider departure';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,p,'start_tracking','{}');r:=mission_workflow_action(m,p,'arrived','{}');
 IF r->>'status'<>'en_route' THEN RAISE EXCEPTION 'ASSERT provider self-confirmed arrival';END IF;checks:=checks+1;
 r:=mission_workflow_action(m,c,'confirm_arrival','{}');
 BEGIN PERFORM mission_workflow_action(m,p,'done','{}');RAISE EXCEPTION 'ASSERT finished without evidence';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);SET LOCAL ROLE authenticated;
 BEGIN INSERT INTO gps_tracking(mission_id,artisan_id,lat,lng) VALUES(m,ap,5.3,-4.0);RAISE EXCEPTION 'ASSERT client posted GPS';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',p::text,true);SET LOCAL ROLE authenticated;
 INSERT INTO gps_tracking(mission_id,artisan_id,lat,lng) VALUES(m,ap,5.3,-4.0);
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub','',true);
 PERFORM mission_workflow_action(m,p,'submit_proof','{"photos":["https://example.test/test-proof.png"],"notes":"[TEST] Mitigeur remplacé et étanchéité contrôlée."}');checks:=checks+2;
 r:=mission_workflow_action(m,p,'done','{}');
 BEGIN PERFORM mission_workflow_action(m,p,'validate','{}');RAISE EXCEPTION 'ASSERT provider validated own work';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 r:=mission_workflow_action(m,c,'validate','{}');r:=mission_workflow_action(m,c,'validate','{}');
 IF r->>'status'<>'completed' OR (SELECT count(*) FROM payment_instructions WHERE mission_id=m)<>1 THEN RAISE EXCEPTION 'ASSERT double release or wrong completion';END IF;checks:=checks+1;
 BEGIN INSERT INTO gps_tracking(mission_id,artisan_id,lat,lng) VALUES(m,ap,5.3,-4.0);RAISE EXCEPTION 'ASSERT GPS after closure';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 -- A second job: client disputes; provider cannot force completion.
 INSERT INTO missions(client_id,category,is_test) VALUES(c,'Plomberie',true) RETURNING id INTO m2;
 PERFORM mission_workflow_action(m2,c,'request_provider',jsonb_build_object('artisan_id',ap));PERFORM mission_workflow_action(m2,p,'accept_assignment','{}');
 PERFORM update_discussion_agreement(m2,c,'confirm',0,'{"scope":"Déboucher le siphon de cuisine, hors matériel","discussion":false}');
 PERFORM update_discussion_agreement(m2,p,'propose',1,'{"scope":"Débouchage et contrôle du siphon de cuisine","reason":"Intervention définie après examen de la demande client","amount":12000,"supplies":"excluded"}');PERFORM update_discussion_agreement(m2,c,'accept',2,'{}');q:=get_client_quote(m2,c);
 PERFORM mission_workflow_action(m2,c,'pay_test',jsonb_build_object('quote_revision',q->>'quote_revision'));PERFORM mission_workflow_action(m2,c,'start_now','{}');PERFORM mission_workflow_action(m2,p,'start_tracking','{}');
 BEGIN INSERT INTO chat_history(mission_id,sender_id,sender_role,type,text) VALUES(m2,c,'client','text','Message malgré le mode sans discussion');RAISE EXCEPTION 'ASSERT discussion disabled bypassed';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 PERFORM mission_workflow_action(m2,c,'dispute','{"reason":"Le prestataire n’est pas présent au lieu convenu."}');
 BEGIN PERFORM mission_workflow_action(m2,c,'validate','{}');RAISE EXCEPTION 'ASSERT disputed mission validated';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 IF EXISTS(SELECT 1 FROM payment_instructions WHERE mission_id=m2) THEN RAISE EXCEPTION 'ASSERT disputed funds released';END IF;checks:=checks+1;
 INSERT INTO missions(client_id,category,is_test) VALUES(c,'Plomberie',true) RETURNING id INTO m3;
 BEGIN PERFORM mission_workflow_action(m3,c,'request_provider',jsonb_build_object('artisan_id',ap2));RAISE EXCEPTION 'ASSERT wrong trade assigned';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 PERFORM mission_workflow_action(m3,c,'request_provider',jsonb_build_object('artisan_id',ap));r:=mission_workflow_action(m3,p,'reject_assignment','{}');
 IF r->>'status'<>'matching' OR r->>'artisan_id' IS NOT NULL THEN RAISE EXCEPTION 'ASSERT provider refusal not handled';END IF;checks:=checks+1;
 PERFORM mission_workflow_action(m3,c,'cancel','{}');
 BEGIN PERFORM mission_workflow_action(m3,c,'request_provider',jsonb_build_object('artisan_id',ap));RAISE EXCEPTION 'ASSERT cancelled mission reused';EXCEPTION WHEN OTHERS THEN IF SQLERRM LIKE 'ASSERT%' THEN RAISE;END IF;END;checks:=checks+1;
 PERFORM mission_workflow_action(m2,admin_uid,'resolve_dispute','{"reason":"[TEST] Absence de prestation confirmée après examen des échanges.","resolution":"refund"}');
 IF (SELECT status FROM missions WHERE id=m2)<>'cancelled' OR (SELECT status FROM payment_instructions WHERE mission_id=m2)<>'simulated' THEN RAISE EXCEPTION 'ASSERT dispute decision not recorded';END IF;checks:=checks+1;
 PERFORM set_config('afrione.test_checks',checks::text,true);
 RAISE NOTICE 'PASS: % business-rule checks; 3 jobs; five distinct identities including two trades, self-provider, outsider and admin; all rolled back',checks;
END $$;
SELECT jsonb_build_object('result','PASS','checks',current_setting('afrione.test_checks')::int,'scenarios',ARRAY['negotiation and rejected increase','confirmed price','arrival and evidence','closure without double release','dispute and administrative refund decision','refusal and cancellation','self-booking and RLS protections'],'fixture_accounts',5,'jobs',3,'rolled_back',true) as result;
ROLLBACK;
